11	namespace duckdb {
12	
13	static void LeftDelimBindScanCollection(const PhysicalLeftDelimJoin &delim_join, ColumnDataCollection &collection) {
14		auto &cast_cached_scan = delim_join.join.children[0].get().Cast<PhysicalColumnDataScan>();
15		cast_cached_scan.collection = &collection;
16	}
17	
18	static void LeftDelimResetSinkState(const PhysicalOperator &op, ClientContext &context,
19	                                    unique_ptr<GlobalSinkState> &state) {
20		if (state && state->SupportsReuse()) {
21			state->Reset(context);
22			return;
23		}
24		state = op.GetGlobalSinkState(context);
25	}
26	
27	static void LeftDelimResetLocalSinkState(const PhysicalOperator &op, ExecutionContext &context, GlobalSinkState &gstate,
28	                                         unique_ptr<LocalSinkState> &state) {
29		if (state && state->SupportsReuse()) {
30			state->Reset(context, gstate);
31			return;
32		}
33		state = op.GetLocalSinkState(context);
34	}
35	
36	PhysicalLeftDelimJoin::PhysicalLeftDelimJoin(PhysicalPlan &physical_plan, PhysicalPlanGenerator &planner,
37	                                             vector<LogicalType> types, PhysicalOperator &original_join,
38	                                             PhysicalOperator &distinct,
39	                                             const vector<const_reference<PhysicalOperator>> &delim_scans,
40	                                             idx_t estimated_cardinality, optional_idx delim_idx)
41	    : PhysicalDelimJoin(physical_plan, PhysicalOperatorType::LEFT_DELIM_JOIN, std::move(types), original_join, distinct,
42	                        delim_scans, estimated_cardinality, delim_idx) {
43		D_ASSERT(join.children.size() == 2);
44		// now for the original join
45		// we take its left child, this is the side that we will duplicate eliminate
46		children.push_back(join.children[0]);
47	
48		// we replace it with a PhysicalColumnDataScan, that scans the ColumnDataCollection that we keep cached
49		// the actual chunk collection to scan will be created in the LeftDelimJoinGlobalState
50		auto &cached_scan = planner.Make<PhysicalColumnDataScan>(
51		    children[0].get().GetTypes(), PhysicalOperatorType::COLUMN_DATA_SCAN, estimated_cardinality, nullptr);
52		if (delim_idx.IsValid()) {
53			auto &cast_cached_scan = cached_scan.Cast<PhysicalColumnDataScan>();
54			cast_cached_scan.delim_index = delim_idx.GetIndex();
55		}
56		join.children[0] = cached_scan;
57	}
58	
59	//===--------------------------------------------------------------------===//
60	// Sink
61	//===--------------------------------------------------------------------===//
62	class LeftDelimJoinGlobalState : public GlobalSinkState {
63	public:
64		explicit LeftDelimJoinGlobalState(ClientContext &context, const PhysicalLeftDelimJoin &delim_join_p)
65		    : delim_join(delim_join_p), lhs_data(context, delim_join_p.children[0].get().GetTypes()) {
66			D_ASSERT(!delim_join_p.delim_scans.empty());
67			LeftDelimBindScanCollection(delim_join_p, lhs_data);
68		}
69	
70		const PhysicalLeftDelimJoin &delim_join;
71		ColumnDataCollection lhs_data;
72		mutex lhs_lock;
73	
74		bool SupportsReuse() const override {
75			return true;
76		}
77	
78		void Reset(ClientContext &context) override {
79			lhs_data.ResetForReuse();
80			LeftDelimBindScanCollection(delim_join, lhs_data);
81			LeftDelimResetSinkState(delim_join.distinct, context, delim_join.distinct.sink_state);
82			if (delim_join.delim_scans.size() > 1) {
83				PhysicalHashAggregate::SetMultiScan(*delim_join.distinct.sink_state);
84			}
85			GlobalSinkState::Reset(context);
86		}
87	
88		void Merge(ColumnDataCollection &input) {
89			if (input.Count() == 0) {
90				return;
91			}
92			lock_guard<mutex> guard(lhs_lock);
93			if (lhs_data.Count() == 0) {
94				lhs_data.Swap(input);
95				LeftDelimBindScanCollection(delim_join, lhs_data);
96				return;
97			}
98			lhs_data.Combine(input);
99		}
100	};
101	
102	class LeftDelimJoinLocalState : public LocalSinkState {
103	public:
104		explicit LeftDelimJoinLocalState(ClientContext &context, const PhysicalLeftDelimJoin &delim_join)
105		    : delim_join(delim_join), lhs_data(context, delim_join.children[0].get().GetTypes()) {
106			lhs_data.InitializeAppend(append_state);
107		}
108	
109		const PhysicalLeftDelimJoin &delim_join;
110	
111		unique_ptr<LocalSinkState> distinct_state;
112		ColumnDataCollection lhs_data;
113		ColumnDataAppendState append_state;
114	
115		bool SupportsReuse() const override {
116			return true;
117		}
118	
119		void Reset(ExecutionContext &context, GlobalSinkState &gstate) override {
120			lhs_data.ResetForReuse();
121			lhs_data.InitializeAppend(append_state);
122			LeftDelimResetLocalSinkState(delim_join.distinct, context, *delim_join.distinct.sink_state, distinct_state);
123		}
124	
125		void Append(DataChunk &input) {
126			lhs_data.Append(input);
127		}
128	};
129	
130	unique_ptr<GlobalSinkState> PhysicalLeftDelimJoin::GetGlobalSinkState(ClientContext &context) const {
131		auto state = make_uniq<LeftDelimJoinGlobalState>(context, *this);
132		distinct.sink_state = distinct.GetGlobalSinkState(context);
133		if (delim_scans.size() > 1) {
134			PhysicalHashAggregate::SetMultiScan(*distinct.sink_state);
135		}
136		return std::move(state);
137	}
138	
139	unique_ptr<LocalSinkState> PhysicalLeftDelimJoin::GetLocalSinkState(ExecutionContext &context) const {
140		auto state = make_uniq<LeftDelimJoinLocalState>(context.client, *this);
141		state->distinct_state = distinct.GetLocalSinkState(context);
142		return std::move(state);
143	}
144	
145	SinkResultType PhysicalLeftDelimJoin::Sink(ExecutionContext &context, DataChunk &chunk,
146	                                           OperatorSinkInput &input) const {
147		auto &lstate = input.local_state.Cast<LeftDelimJoinLocalState>();
148		lstate.lhs_data.Append(lstate.append_state, chunk);
149		OperatorSinkInput distinct_sink_input {*distinct.sink_state, *lstate.distinct_state, input.interrupt_state};
150		distinct.Sink(context, chunk, distinct_sink_input);
151		return SinkResultType::NEED_MORE_INPUT;
152	}
153	
154	SinkCombineResultType PhysicalLeftDelimJoin::Combine(ExecutionContext &context, OperatorSinkCombineInput &input) const {
155		auto &lstate = input.local_state.Cast<LeftDelimJoinLocalState>();
156		auto &gstate = input.global_state.Cast<LeftDelimJoinGlobalState>();
157		gstate.Merge(lstate.lhs_data);
158	
159		OperatorSinkCombineInput distinct_combine_input {*distinct.sink_state, *lstate.distinct_state,
160		                                                 input.interrupt_state};
161		distinct.Combine(context, distinct_combine_input);
162	
163		return SinkCombineResultType::FINISHED;
164	}
165	
166	void PhysicalLeftDelimJoin::PrepareFinalize(ClientContext &context, GlobalSinkState &sink_state) const {
167		distinct.PrepareFinalize(context, *distinct.sink_state);
168	}
169	
170	SinkFinalizeType PhysicalLeftDelimJoin::Finalize(Pipeline &pipeline, Event &event, ClientContext &client,
171	                                                 OperatorSinkFinalizeInput &input) const {
172		// Finalize the distinct hash table.
173		OperatorSinkFinalizeInput finalize_input {*distinct.sink_state, input.interrupt_state};
174		distinct.Finalize(pipeline, event, client, finalize_input);
175		return SinkFinalizeType::READY;
176	}
177	
178	//===--------------------------------------------------------------------===//
179	// Pipeline Construction
180	//===--------------------------------------------------------------------===//
181	void PhysicalLeftDelimJoin::BuildPipelines(Pipeline &current, MetaPipeline &meta_pipeline) {
182		op_state.reset();
183		sink_state.reset();
184	
185		auto &child_meta_pipeline = meta_pipeline.CreateChildMetaPipeline(current, *this);
186		child_meta_pipeline.Build(children[0]);
187	
188		D_ASSERT(type == PhysicalOperatorType::LEFT_DELIM_JOIN);
189		// recurse into the actual join
190		// any pipelines in there depend on the main pipeline
191		// any scan of the duplicate eliminated data on the RHS depends on this pipeline
192		// we add an entry to the mapping of (PhysicalOperator*) -> (Pipeline*)
193		auto &state = meta_pipeline.GetState();
194		for (auto &delim_scan : delim_scans) {
195			state.delim_join_dependencies.insert(
196			    make_pair(delim_scan, reference<Pipeline>(*child_meta_pipeline.GetBasePipeline())));
197		}
198		join.BuildPipelines(current, meta_pipeline);
199	}
200	
201	} // namespace duckdb
