19	static idx_t ColumnDataScanBatchCount(idx_t count, idx_t batch_size) {
20		return MaxValue<idx_t>(count / batch_size + (count % batch_size != 0), 1);
21	}
22	
23	static idx_t GetColumnDataScanBatchSize(ClientContext &context, idx_t collection_count,
24	                                        const OperatorPartitionInfo &partition_info) {
25		if (ClientConfig::GetConfig(context).verify_parallelism) {
26			return STANDARD_VECTOR_SIZE;
27		}
28		if (!partition_info.RequiresBatchIndex()) {
29			return STANDARD_VECTOR_SIZE;
30		}
31		idx_t preferred_batch_size = DEFAULT_ROW_GROUP_SIZE;
32		if (partition_info.preferred_batch_size.IsValid() && partition_info.preferred_batch_size.GetIndex() > 0) {
33			preferred_batch_size = partition_info.preferred_batch_size.GetIndex();
34		}
35		auto thread_count = MaxValue<idx_t>(TaskScheduler::GetScheduler(context).NumberOfThreads(), 1);
36		auto rows_per_thread = collection_count / thread_count + (collection_count % thread_count != 0);
37		auto parallelism_cap = MaxValue<idx_t>(STANDARD_VECTOR_SIZE, rows_per_thread);
38		return MinValue(preferred_batch_size, parallelism_cap);
39	}
