106		bool AssignTask(const ColumnDataCollection &collection, PhysicalColumnDataGlobalScanState &gstate) {
107			entries.clear();
108			entry_index = 0;
109			batch_index = DConstants::INVALID_INDEX;
110	
111			idx_t task_count = 0;
112			lock_guard<mutex> l(gstate.global_scan_state.lock);
113			while (task_count < gstate.batch_size) {
114				idx_t chunk_index;
115				idx_t segment_index;
116				idx_t row_index;
117				if (!collection.NextScanIndex(gstate.global_scan_state.scan_state, chunk_index, segment_index, row_index)) {
118					break;
119				}
120				entries.emplace_back(chunk_index, segment_index, row_index);
121				task_count += collection.GetSegments()[segment_index]->chunk_data[chunk_index].count;
122			}
123	
124			if (entries.empty()) {
125				return false;
126			}
127			batch_index = gstate.next_batch_index++;
128			return true;
129		}
