218	void PhysicalColumnDataScan::BuildPipelines(Pipeline &current, MetaPipeline &meta_pipeline) {
219		// check if there is any additional action we need to do depending on the type
220		auto &state = meta_pipeline.GetState();
221		switch (type) {
222		case PhysicalOperatorType::DELIM_SCAN: {
223			auto entry = state.delim_join_dependencies.find(*this);
224			D_ASSERT(entry != state.delim_join_dependencies.end());
225			// this chunk scan introduces a dependency to the current pipeline
226			// namely a dependency on the duplicate elimination pipeline to finish
227			auto delim_dependency = entry->second.get().shared_from_this();
228			auto delim_sink = state.GetPipelineSink(*delim_dependency);
229			D_ASSERT(delim_sink);
230			D_ASSERT(delim_sink->type == PhysicalOperatorType::LEFT_DELIM_JOIN ||
231			         delim_sink->type == PhysicalOperatorType::RIGHT_DELIM_JOIN);
232			auto &delim_join = delim_sink->Cast<PhysicalDelimJoin>();
233			current.AddDependency(delim_dependency);
234			state.SetPipelineSource(current, delim_join.distinct.Cast<PhysicalOperator>());
235			return;
236		}
237		case PhysicalOperatorType::CTE_SCAN: {
238			if (cte_source) {
239				auto entry = state.cte_dependencies.find(*this);
240				D_ASSERT(entry != state.cte_dependencies.end());
241				auto cte_dependency = entry->second.get().shared_from_this();
242				auto cte_sink = state.GetPipelineSink(*cte_dependency);
243				D_ASSERT(cte_sink);
244				D_ASSERT(cte_sink->type == PhysicalOperatorType::CTE);
245				auto &cte = cte_sink->Cast<PhysicalCTE>();
246				auto &source = cte_source->Cast<PhysicalCTEConsumerSource>();
247				// Prefer direct fanout. Buffered exchange is only used when it can avoid full materialization or
248				// when the consumer can stop early; otherwise this scan reads the materialized working table.
249				auto has_blocking_dependencies = !current.GetDependencies().empty();
250				if (cte.CanRegisterDirectConsumer(current) &&
251				    (!cte.cte_body_has_side_effects || has_blocking_dependencies)) {
252					D_ASSERT(collection);
253					current.AddDependency(cte_dependency);
254					state.AddExternalInputCandidate(current, *this, *cte_source, cte_dependency, cte, source.consumer_idx);
255					state.SetPipelineSource(current, *this);
256					return;
257				}
258				if (cte.TryRegisterDirectConsumer(current, source.consumer_idx)) {
259					DUCKDB_LOG(current.GetClientContext(), PhysicalOperatorLogType, cte, "PhysicalCTE", "SelectConsumer",
260					           {{"consumer", to_string(source.consumer_idx)}, {"mode", "DIRECT"}});
261					state.SetPipelineSource(current, *cte_source);
262					return;
263				}
264				if (cte.ShouldUseBufferedConsumer(current)) {
265					cte.RegisterBufferedConsumer(current, source.consumer_idx);
266					current.AddDataflowDependency(cte_dependency);
267					DUCKDB_LOG(current.GetClientContext(), PhysicalOperatorLogType, cte, "PhysicalCTE", "SelectConsumer",
268					           {{"consumer", to_string(source.consumer_idx)}, {"mode", "BUFFERED"}});
269					state.SetPipelineSource(current, *cte_source);
270					return;
271				}
272				D_ASSERT(collection);
273				cte.RegisterMaterializedConsumer(source.consumer_idx);
274				current.AddDependency(cte_dependency);
275				DUCKDB_LOG(current.GetClientContext(), PhysicalOperatorLogType, cte, "PhysicalCTE", "SelectConsumer",
276				           {{"consumer", to_string(source.consumer_idx)}, {"mode", "MATERIALIZED"}});
277				state.SetPipelineSource(current, *this);
278				return;
279			}
280			auto entry = state.cte_dependencies.find(*this);
281			D_ASSERT(entry != state.cte_dependencies.end());
282			// this chunk scan introduces a dependency to the current pipeline
283			// namely a dependency on the CTE pipeline to finish
284			auto cte_dependency = entry->second.get().shared_from_this();
285			auto cte_sink = state.GetPipelineSink(*cte_dependency);
286			(void)cte_sink;
287			D_ASSERT(cte_sink);
288			D_ASSERT(cte_sink->type == PhysicalOperatorType::CTE);
289			current.AddDependency(cte_dependency);
290			state.SetPipelineSource(current, *this);
291			return;
292		}
293		case PhysicalOperatorType::RECURSIVE_RECURRING_CTE_SCAN:
294		case PhysicalOperatorType::RECURSIVE_CTE_SCAN:
295			if (!meta_pipeline.HasRecursiveCTE()) {
296				throw InternalException("Recursive CTE scan found without recursive CTE node");
297			}
298			break;
299		default:
300			break;
301		}
302		D_ASSERT(children.empty());
303		state.SetPipelineSource(current, *this);
304	}
305	
306	InsertionOrderPreservingMap<string> PhysicalColumnDataScan::ParamsToString() const {
307		InsertionOrderPreservingMap<string> result;
308		switch (type) {
309		case PhysicalOperatorType::DELIM_SCAN:
310			if (delim_index.IsValid()) {
311				result["Delim Index"] = StringUtil::Format("%llu", delim_index.GetIndex());
312			}
313			break;
314		case PhysicalOperatorType::RECURSIVE_RECURRING_CTE_SCAN:
315		case PhysicalOperatorType::CTE_SCAN:
316		case PhysicalOperatorType::RECURSIVE_CTE_SCAN: {
317			result["CTE Index"] = StringUtil::Format("%llu", cte_index.index);
318			break;
319		}
320		default:
321			break;
322		}
323		SetEstimatedCardinality(result, estimated_cardinality);
324		return result;
325	}
